import {freshRoad,restoreRoad,roadObjective} from './road-state.mjs';
import {advanceJourney,restoreJourneyPhase} from './journey-state.mjs';
// Render-independent game rules. Dialogue is original game writing, not film dialogue.
import {MAP_BOUNDS} from './village-layout.mjs';
export const SAVE_KEY='shire-journey-morning-v1';
// Preserve real-time movement at low render FPS, but ignore huge stalled-tab jumps.
export function frameDelta(elapsedMs){return Math.max(0,Math.min(elapsedMs/1000,.2));}
export const NPCS=[{id:'bilbo',name:'بيلبو',en:'Bilbo',x:8,z:7},{id:'sam',name:'سام',en:'Sam',x:-6,z:1},{id:'gandalf',name:'غاندالف',en:'Gandalf',x:-2,z:17},{id:'frodo',name:'فرودو',en:'Frodo',x:3,z:-4}];
export const PARTY_TREE=Object.freeze({id:'party-tree',name:'شجرة احتفال بيلبو',x:-2,z:21});
export const APPLES=[{id:'apple-0',x:-18,z:12},{id:'apple-1',x:-17,z:17},{id:'apple-2',x:-21,z:15}];
export function freshState(){return {version:1,road:freshRoad(),journeyPhase:'birthday',stage:0,apples:[],visited:[],position:{x:0,z:-15},completed:false,insideVisited:false,gandalfMet:false,partyStarted:false,partyCompleted:false,bilboGone:false,ringPassed:false,applesSkipped:false,memories:[],ringInspections:0};}
export function restoreState(raw){try{const s=JSON.parse(raw);if(!s||s.version!==1)return freshState();const valid=Number.isInteger(s.stage)&&s.stage>=0&&s.stage<=5&&Array.isArray(s.apples)&&Array.isArray(s.visited)&&s.position&&Number.isFinite(s.position.x)&&Number.isFinite(s.position.z)&&s.position.x>MAP_BOUNDS.minX+1&&s.position.x<MAP_BOUNDS.maxX-1&&s.position.z>MAP_BOUNDS.minZ+1&&s.position.z<MAP_BOUNDS.maxZ-1; if(!valid)return freshState();const apples=[...new Set(s.apples.filter(id=>APPLES.some(a=>a.id===id)))];if(s.stage>=3&&apples.length!==3&&!(s.stage>=4&&s.applesSkipped===true))return freshState();if((s.partyStarted===true||s.partyCompleted===true)&&s.stage!==5)return freshState();return {...freshState(),road:restoreRoad(s.road,restoreJourneyPhase(s.journeyPhase,s.partyCompleted===true)),journeyPhase:restoreJourneyPhase(s.journeyPhase,s.partyCompleted===true),stage:s.stage,apples,visited:[...new Set(s.visited.filter(id=>NPCS.some(n=>n.id===id)))],position:{x:s.position.x,z:s.position.z},completed:s.stage===5,insideVisited:s.insideVisited===true,ringInspections:s.partyCompleted===true&&Number.isInteger(s.ringInspections)?Math.max(0,Math.min(999,s.ringInspections)):0,gandalfMet:s.gandalfMet===true||s.stage>0,partyStarted:s.partyStarted===true||s.partyCompleted===true,partyCompleted:s.partyCompleted===true,bilboGone:s.partyCompleted===true,ringPassed:s.partyCompleted===true,applesSkipped:s.applesSkipped===true,memories:Array.isArray(s.memories)?s.memories.filter(v=>v&&NPCS.some(n=>n.id===v.id)&&typeof v.topic==='string'&&/^[a-z]{2,20}$/.test(v.topic)).slice(-16).map(v=>({id:v.id,topic:v.topic})):[]};}catch{return freshState();}}
export function objective(s){if(s.journeyPhase==='roads')return roadObjective(s.road||freshRoad());if(s.journeyPhase==='investigation')return 'غاندالف يبحث عن أصل الخاتم؛ ادخل باج إند واقترب من المدفأة';if(s.journeyPhase==='revelation')return 'شاهد عودة غاندالف وكشف حقيقة الخاتم';if(['departure','roads'].includes(s.journeyPhase))return 'أنت فرودو الآن؛ سام يرافقك؛ اتبع الدرب جنوبًا إلى مخرج القرية';if(s.stage===0)return s.gandalfMet?'قابل بيلبو عند الباب الأخضر':'حيِّ غاندالف العائد إلى الشاير';if(s.stage===5)return s.partyCompleted?'انتهى الاحتفال؛ تحدّث مع فرودو عن رحلة بيلبو':s.partyStarted?'شاهد الاحتفال ووداع بيلبو':'توجّه إلى شجرة الاحتفال لبدء الحفلة';return ['','تحدّث مع سام عند الحديقة',`ارجع إلى سام أو اجمع التفّاح (اختياري) · ${s.apples.length}/3`,'أعد التفّاح إلى سام','أخبر بيلبو أنّ التحضير اكتمل'][s.stage];}
export function nearestInteractable(s,p,npcs=NPCS){const objects=[...npcs.filter(n=>!(s.partyCompleted&&n.id==='bilbo')&&!(n.id==='gandalf'&&['investigation','revelation','departure','roads'].includes(s.journeyPhase))&&!(n.id==='frodo'&&['departure','roads'].includes(s.journeyPhase))),...(s.stage===2?APPLES.filter(a=>!s.apples.includes(a.id)):[]),...(s.stage===5&&!s.partyStarted?[PARTY_TREE]:[])];return objects.map(o=>({...o,distance:Math.hypot(o.x-p.x,o.z-p.z)})).filter(o=>o.distance<2.5).sort((a,b)=>a.distance-b.distance)[0]||null;}
export function talk(s,id){if(!NPCS.some(n=>n.id===id))return false;if(!s.visited.includes(id))s.visited.push(id);return true;}
export function act(s,action){if(action==='greet-wizard'&&s.stage===0&&!s.gandalfMet){s.gandalfMet=true;return true;}if(action==='start-party'&&s.stage===5&&!s.partyStarted){s.partyStarted=true;return true;}if(action==='party-finalize'&&s.stage===5&&s.partyStarted&&!s.partyCompleted){s.partyCompleted=true;s.bilboGone=true;s.ringPassed=true;return true;}if(action==='accept'&&s.stage===0&&s.gandalfMet){s.stage=1;return true;}if(action==='basket'&&s.stage===1){s.stage=2;return true;}if(action==='skip-apples'&&(s.stage===1||s.stage===2)){s.stage=4;s.applesSkipped=true;return true;}if(action==='deliver'&&s.stage===2&&s.apples.length===3){s.stage=3;return true;}if(action==='thank-sam'&&s.stage===3){s.stage=4;return true;}if(action==='finish'&&s.stage===4){s.stage=5;s.completed=true;return true;}return advanceJourney(s,action);}
export function collect(s,id,p){const a=APPLES.find(a=>a.id===id);if(!a||s.stage!==2||s.apples.includes(id)||Math.hypot(a.x-p.x,a.z-p.z)>=2.5)return false;s.apples.push(id);if(s.apples.length===3)act(s,'deliver');return true;}
export function dialogue(s,id){
 if(id==='bilbo'){
  if(s.stage===0&&!s.gandalfMet)return {text:'غاندالف عاد إلى الشاير، وقد سمع الناس صوت عربته في الطريق. حيّه أولًا ثم عد إليّ؛ فالحفلة تحتاج إلى أصدقاء يساعدوننا.',options:[['سأرحّب به ثم أعود.','close']]};
  if(s.stage===0)return {text:'أهلًا بك! يوم جميل للمشي، أليس كذلك؟ أجهّز لقاءً صغيرًا للأصدقاء تحت الشجرة الكبيرة. هل تساعدني؟ سام ينتظر قرب الحديقة.',options:[['بكل سرور، سأذهب إلى سام.','accept'],['احكِ لي عن هذا المكان.','bilbo-lore'],['سأتمشّى قليلًا أولًا.','close']]};
  if(s.partyCompleted)return {text:'ترك بيلبو بيته وذكرياته خلفه واختار أن يسافر بعد الحفلة. الآن يحمل فرودو أمرًا جديدًا، وستتغيّر الأيام شيئًا فشيئًا.',options:[['سأبحث عن فرودو.','close']]};
  if(s.stage===4)return {text:s.apples.length===3?'ها أنت! رائحة التفّاح وصلت قبلك. سام أخبرني عن مساعدتك. تعال، هناك دائمًا مكان لصديق جديد تحت شجرة الحفل.':'سام يتابع تحضيرات الحفلة، وهناك ما هو أهم من سلال البستان: لنتوجّه إلى الشجرة الكبيرة لنشهد هذه الليلة.',options:[['يسعدني أن أبقى معكم.','finish'],['سأعود بعد قليل.','close']]};
  return {text:s.completed?'اكتملت التحضيرات! خذ وقتك، واستمتع بالمكان. تستطيع زيارة غاندالف أو العودة إلى البستان.':'ستجد سام عند الحديقة أسفل الطريق. لا تستعجل؛ الشاير أجمل عندما نمشي على مهل.',options:[['احكِ لي عن الشاير.','bilbo-lore'],['إلى اللقاء يا بيلبو.','close']]};
 }
 if(id==='sam'){
  if(['departure','roads'].includes(s.journeyPhase))return {text:'لن أتركك تقطع الطريق وحدك يا سيد فرودو. معي الزاد، وسأمشي خلفك حتى نتجاوز هذه التلال.',options:[['نبقى معًا ونراقب الطريق.','close']]};
  if(s.partyCompleted)return {text:'هدأت الساحة بعد الحفلة، وبيلبو مضى في رحلته. أرتّب الحديقة الآن؛ إن رأيت فرودو فابقَ معه قليلًا.',options:[['سأمرّ قرب البيت.','close'],['حدّثني عن الحديقة.','sam-lore']]};
  if(s.stage===1)return {text:'أرسلك بيلبو؟ ممتاز! نحتاج ثلاث تفّاحات من البستان خلفي. اتبع الطريق الصغير إلى الأشجار الحمراء، ثم ارجع إليّ.',options:[['أساعد في جمع التفّاح (اختياري).','basket'],['أكمل الحكاية إلى حفلة بيلبو.','skip-apples'],['كيف أصل إلى البستان؟','sam-lore'],['سأعود قريبًا.','close']]};
  if(s.stage===3)return {text:'تفّاح ممتاز! سأجهّز السلال وألحق بكم. أخبر بيلبو أنّ كل شيء صار جاهزًا. شكرًا على مساعدتك.',options:[['سأوصل له الخبر.','thank-sam'],['لحظة، أريد أن أسألك.','sam-lore']]};
  return {text:s.stage===2?`يمكنك جمع التفّاح من البستان إذا أحببت، لكنه نشاط جانبي وليس من أحداث القصة. جمعت ${s.apples.length} من ثلاث تفّاحات.`:'أهلًا! أحب هذه الساعة؛ الحديقة هادئة والهواء لطيف. هل زرت بيلبو عند الباب الأخضر؟',options:s.stage===2?[['أريد متابعة حفلة بيلبو الآن.','skip-apples'],['سأكمل التفّاح.','close'],['أين البستان؟','sam-lore']]:[['احكِ لي عن الحديقة.','sam-lore'],['إلى اللقاء يا سام.','close']]};
 }
 if(id==='frodo'){if(s.partyCompleted)return {text:'انتهت ليلة عيد ميلاد بيلبو، لكنه مضى في طريقه تاركًا كتبه وبيته وخاتمًا غريبًا. أحتاج إلى هدوء قليل وإلى نصيحة غاندالف قبل أن أعرف معنى ما حدث.',options:[['ستجدني بالقرب من البيت.','close'],['حدّثني عن بيلبو.','frodo-lore']]};return {text:'صباح الخير! أساعد عمي بيلبو في التجهيز للاحتفال، وأترقّب قصص غاندالف عن السفر. هل تعرف الطريق إلى الشجرة الكبيرة؟',options:[['احكِ لي عن الاحتفال.','frodo-lore'],['سأستكشف القرية.','close']]};}
 if(id==='gandalf'&&s.partyCompleted&&(s.journeyPhase||'birthday')==='birthday')return {text:'هناك أمر يقلقني في خاتم بيلبو. سأبحث في السجلات القديمة عن أصله. احتفظ به في مكان أمين، ثم انتظرني قرب مدفأة باج إند.',options:[['ابحث عن حقيقة الخاتم.','research-ring'],['سأعود بعد قليل.','close']]};
 if(id==='gandalf'&&s.stage===0&&!s.gandalfMet)return {text:'أعود دائمًا إلى هذه التلال بسرور. شاهدت فرودو في الطريق، وسمعت أن بيلبو يستعد لليلة لا تُنسى. اذهب إليه بعد أن تلقي التحية؛ فمساعدته ستجعل الفرح يعم القرية.',options:[['أهلًا بعودتك، سأقابل بيلبو.','greet-wizard'],['احكِ لي عن الدروب.','gandalf-lore']]};
 if(s.partyCompleted)return {text:'كان بيلبو يحمل شوقًا إلى الطرق البعيدة. رحل بعد الاحتفال، وترك فرودو أمام أسئلة تستحق بعض الوقت. الرفق به الآن أهم من أي مغامرة سريعة.',options:[['سأتحدّث مع فرودو.','close'],['كيف تبدأ الرحلات؟','gandalf-lore']]};
 return {text:'القرية تستعد للغناء والأنوار. ما أجمل أن يلتقي أهل الشاير قبل أن تقودهم الطرق إلى حكايات أكبر.',options:[['إلى أين تقود الطرق؟','gandalf-lore'],['إلى اللقاء.','close']]};
}
export const LORE={
 'bilbo-lore':'هنا بيوت صغيرة وحدائق يعتني بها أصحابها. خلف كل باب حكاية، وعلى كل طريق فرصة للقاء جار. اليوم نأخذ استراحة للاحتفال بالصداقة.',
 'sam-lore':'أعتني بالزهور والخضار هنا. البستان وراء السياج الخشبي إلى الغرب؛ التفّاح المطلوب يلمع قرب الأرض. اقترب واضغط زر التفاعل.',
 'gandalf-lore':'من هذه التلال تتفرّع دروب نحو الأنهار والغابات، ومن هناك إلى بلدة بري. أمّا اليوم فينبغي أن نعيش فرحة الاحتفال قبل أن يحين وقت السفر.',
 'frodo-lore':'نحضّر لقاءً تحت الشجرة الكبيرة. عمّي بيلبو يهتم بالضيوف وسام بالحديقة، وغاندالف يجلب المفاجآت. لا أعرف بعد كيف سيكون هذا اليوم.'
};

export function loreForState(s,topic){
 if(s.partyCompleted&&topic==='frodo-lore')return 'سافر عمي بعد ليلة عيد ميلاده، وترك لي البيت وكتبه. ما زلت أتعلّم كيف يكون المكان من دون خطواته بين الغرف.';
 if(s.partyCompleted&&topic==='gandalf-lore')return 'تتفرّع الطرق من الشاير نحو النهر وبري، لكن السفر لا يبدأ قبل الاستعداد له. ما زال فرودو هنا، وله أسئلة ينبغي ألا نستعجل أجوبتها.';
 return LORE[topic];
}
